 unsigned actual=0;for(const auto&entry:{std::pair<const char*,EffectProfile50BE>{"podLeftEngineSmoke.emt",EffectProfile50BE::Particle19A5E0},{"podRightEngineSmoke.emt",EffectProfile50BE::Particle19A5E0},{"podLeftEngineDust.emt",EffectProfile50BE::Particle19A5E0},{"podRightEngineDust.emt",EffectProfile50BE::Particle19A5E0},{"podSparks.emt",EffectProfile50BE::Ordinary15F100},{"podFire.emt",EffectProfile50BE::Fire15DE00}}){std::ifstream in(std::string("evidence/effectAuthoring50BF/members/")+entry.first);std::string raw((std::istreambuf_iterator<char>(in)),{});EffectOwner50BE owner{};auto before=allocations;if(!buildEffectControlOwner50BJ(200+actual,entry.second,raw.data(),raw.size(),{0,0},owner)||allocations!=before||owner.state.flags1D4!=1||owner.state.velocity60[3]!=0x3f800000u||owner.mode1D8||owner.duration1E4)return 1;++actual;}
